INSERT OR IGNORE INTO bitacora_criterio (id, tema, decision, fundamento, quien, fecha, estado, observaciones) VALUES
('C13', 'CEAV patronal: primer renglón en salario mínimo', 'Por decidir. Hoy el primer renglón se lee como 1.00 UMA; el transitorio de la reforma (DOF 16-dic-2020) dice «1.00 SM» y «1.01 SM a 1.50 UMA»', 'LSS art. 168 fr. II y Segundo Transitorio; cotejo del 19-oct-2026', 'Pendiente (Rafael)', '2026-10-19', 'abierto', 'Sólo cambia el resultado cuando el SBC es exactamente un salario mínimo (315.04 = 2.68 UMA): con la lectura en UMA va a 6.026%, con la lectura en SM a 3.150%. Caso dorado D41.'),
('C14', 'Cuota obrera de quien gana el salario mínimo', 'Por decidir. El kernel calcula cuota obrera aunque el SBC sea el salario mínimo', 'LSS art. 36: el patrón paga íntegramente la cuota del trabajador que percibe el salario mínimo', 'Pendiente (Rafael)', '2026-10-19', 'abierto', 'Definir si se mide por salario diario o por SBC y cómo se presenta (obrera 0 y patronal + obrera). Caso dorado D41.'),
('C15', 'ISN Sinaloa', 'Hoy 3% plano en nivel C (limitado). La LH Sinaloa (arts. 17–18, fuente secundaria) trae tarifa progresiva 2.4%–3% por tramos mensuales', 'Cotejo del 19-oct-2026', 'Pendiente (Rafael / HRM)', '2026-10-19', 'abierto', 'Con nómina menor a 900,000 al mes el 3% plano cobra de más (600,000 → 18,000 vs 14,600). Confirmar con la ley vigente y modelar como tabla.');
